import os
import unicodedata
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from typing import Optional, Tuple, List
import re

# Security configuration
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.html', '.css', '.js'}
MAX_PATH_LENGTH = 256
BASE_DIR = '/srv/static/public'
RESTRICTED_DIRS = {'/srv/static/public/admin', '/srv/static/public/internal', '/srv/static/public/config'}


def _is_within(path: str, base: str) -> bool:
    """Return True if `path` is `base` itself or a path contained within it.

    Uses a separator-aware comparison to avoid sibling-directory prefix
    bypasses (e.g. /srv/static/public_secret vs /srv/static/public).
    """
    norm_path = os.path.normpath(path)
    norm_base = os.path.normpath(base)
    if norm_path == norm_base:
        return True
    return norm_path.startswith(norm_base + os.sep)


class AccessPolicy:
    """Role-based access control for file serving."""

    def __init__(self):
        self._policies = {
            'anonymous': {'allowed_paths': ['/srv/static/public/docs', '/srv/static/public/assets']},
            'user': {'allowed_paths': ['/srv/static/public/docs', '/srv/static/public/assets', '/srv/static/public/user']},
            'admin': {'allowed_paths': ['/srv/static/public/']},
        }

    def get_allowed_paths(self, role: str) -> List[str]:
        policy = self._policies.get(role, self._policies['anonymous'])
        return policy['allowed_paths']

    def is_path_allowed(self, path: str, role: str) -> bool:
        """Check if the given path is allowed for the role."""
        allowed = self.get_allowed_paths(role)
        # Ensure path is within one of the allowed directories (separator-aware).
        return any(_is_within(path, prefix) for prefix in allowed)


def _sanitize_path_component(component: str) -> str:
    """Remove dangerous characters from a single path component."""
    # Strip null bytes and control characters
    cleaned = ''.join(c for c in component if ord(c) >= 0x20 and c != '\x7f')
    # Remove leading/trailing dots and spaces
    cleaned = cleaned.strip('. ')
    return cleaned


def _check_path_traversal(path: str) -> bool:
    """Returns True if path contains traversal attempts."""
    # Check for obvious traversal patterns
    if '..' in path:
        return True
    if '\\' in path:
        return True
    # Check for encoded traversal
    if '%2e' in path.lower() or '%2f' in path.lower():
        return True
    return False


def _resolve_path_safely(requested_path: str) -> Optional[str]:
    """Resolve path ensuring it stays within BASE_DIR."""
    try:
        # Join with base directory
        full_path = os.path.join(BASE_DIR, requested_path.lstrip('/'))
        # Resolve to absolute path
        resolved = os.path.realpath(full_path)
        # Verify it's still under BASE_DIR (separator-aware to prevent
        # sibling-directory prefix bypasses).
        if not _is_within(resolved, BASE_DIR):
            return None
        return resolved
    except (ValueError, OSError):
        return None


def normalize_unicode_path(path: str) -> str:
    """Normalize Unicode in path to NFC form for consistent handling.

    This prevents Unicode equivalence attacks where visually identical
    characters have different byte representations (e.g., \u0041 vs \u0391).
    """
    # NFC normalization composes characters
    normalized = unicodedata.normalize('NFC', path)
    # Also handle NFKC for compatibility decomposition
    normalized = unicodedata.normalize('NFKC', normalized)
    return normalized


def validate_and_serve(requested_path: str, user_role: str) -> Tuple[int, str]:
    """Main entry point for file serving with security checks.

    Security pipeline:
    1. Length check
    2. Unicode normalization (FIRST for consistent security checks)
    3. Path traversal check
    4. Extension whitelist
    5. Access policy check
    6. Path resolution and serving
    """
    policy = AccessPolicy()

    # Step 1: Length validation
    if len(requested_path) > MAX_PATH_LENGTH:
        return (400, 'Path too long')

    # Step 2: Normalize Unicode BEFORE any security checks
    # This ensures all checks operate on the canonical form
    normalized_path = normalize_unicode_path(requested_path)

    # Step 3: Traversal detection (on normalized path)
    if _check_path_traversal(normalized_path):
        return (403, 'Path traversal detected')

    # Step 4: Extension whitelist (on normalized path)
    ext = PurePosixPath(normalized_path).suffix.lower()
    if ext and ext not in ALLOWED_EXTENSIONS:
        return (403, 'File type not allowed')

    # Step 5: Construct full path and check access policy
    candidate_path = os.path.join(BASE_DIR, normalized_path.lstrip('/'))

    # Check against restricted directories (separator-aware)
    for restricted in RESTRICTED_DIRS:
        if _is_within(candidate_path, restricted):
            if user_role != 'admin':
                return (403, 'Access denied to restricted area')

    # Check role-based access
    if not policy.is_path_allowed(candidate_path, user_role):
        return (403, 'Access denied by policy')

    # Step 6: Resolve the normalized path
    resolved = _resolve_path_safely(normalized_path)
    if resolved is None:
        return (404, 'File not found')

    # Final restricted directory check on resolved path (separator-aware)
    for restricted in RESTRICTED_DIRS:
        if _is_within(resolved, restricted):
            if user_role != 'admin':
                return (403, 'Access denied')

    # Serve the file
    if os.path.isfile(resolved):
        return (200, f'Serving: {resolved}')
    else:
        return (404, 'File not found')


def handle_request(method: str, path: str, headers: dict) -> Tuple[int, str]:
    """HTTP request handler with authentication."""
    if method != 'GET':
        return (405, 'Method not allowed')

    # Extract auth token
    auth_header = headers.get('Authorization', '')
    role = _authenticate(auth_header)

    return validate_and_serve(path, role)


def _authenticate(auth_header: str) -> str:
    """Authenticate user and return role. Defaults to anonymous."""
    if not auth_header:
        return 'anonymous'

    try:
        scheme, token = auth_header.split(' ', 1)
        if scheme.lower() != 'bearer':
            return 'anonymous'

        # Verify token (simplified - in production use JWT)
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        # Admin token check
        admin_token_hash = os.environ.get('ADMIN_TOKEN_HASH', '')
        user_token_hash = os.environ.get('USER_TOKEN_HASH', '')

        # If the expected hashes are not configured, do not authenticate
        # (prevents matching against an empty configured value).
        if admin_token_hash and hmac.compare_digest(token_hash, admin_token_hash):
            return 'admin'
        elif user_token_hash and hmac.compare_digest(token_hash, user_token_hash):
            return 'user'
        else:
            return 'anonymous'
    except (ValueError, AttributeError):
        return 'anonymous'
